1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
9	const COMPONENT_BLOCK_BASE = 60;
10	const COMPONENT_BLOCK_SIZE = 3;
11	
12	const BASE_PREMIUM: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	  potion: 40,
17	  rune: 25,
18	  moonstone: 25,
19	};
20	
21	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
22	
23	type Item = { type: string; cursed?: boolean; enchantment?: number };
24	type Customer = { yearsWithMHPCO: number };
25	type Step = { op: "quote"; items: Item[] };
26	type Scenario = { customer: Customer; steps: Step[] };
27	
28	const countByType = (items: Item[]): Map<string, number> =>
29	  items.reduce(
30	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
31	    new Map<string, number>(),
32	  );
33	
34	const basePremiumForType = (type: string): number => BASE_PREMIUM[type];
35	
36	const basePremiumForGroup = (type: string, count: number): number =>
37	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
38	    ? COMPONENT_BLOCK_BASE
39	    : count * basePremiumForType(type);
40	
41	const basePremiumForItems = (items: Item[]): number =>
42	  [...countByType(items)].reduce(
43	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
44	    0,
45	  );
46	
47	const surchargeRateForItem = (item: Item): number =>
48	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
49	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
50	
51	const itemSurcharges = (items: Item[]): number =>
52	  items.reduce(
53	    (sum, item) => sum + basePremiumForType(item.type) * surchargeRateForItem(item),
54	    0,
55	  );
56	
57	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
58	
59	const loyaltyDiscountRate = (customer: Customer): number =>
60	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
61	
62	const followupDiscountRate = (quoteIndex: number): number =>
63	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
64	
65	const withPolicyWideModifiers = (
66	  base: number,
67	  customer: Customer,
68	  quoteIndex: number,
69	): number =>
70	  base +
71	  base * FIRST_INSURANCE_SURCHARGE_RATE -
72	  base * loyaltyDiscountRate(customer) -
73	  base * followupDiscountRate(quoteIndex);
74	
75	const quotePremium = (
76	  { items }: Step,
77	  customer: Customer,
78	  quoteIndex: number,
79	): number =>
80	  roundInMHPCOsFavor(
81	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
82	      itemSurcharges(items),
83	  ) + PROCESSING_FEE;
84	
85	export const runScenario = ({ customer, steps }: Scenario): { results: Array<{ premium: number }> } => ({
86	  results: steps.map((step, index) => ({ premium: quotePremium(step, customer, index) })),
87	});
