const priorQuoteCount = (steps: Step[], upToIndex: number): number =>
  steps.slice(0, upToIndex).filter((step) => step.op === "quote").length;

export const runScenario = ({ customer, steps }: Scenario): { results: Array<{ premium: number }> } => ({
  results: steps.map((step, index) => ({
    premium: quotePremium(step, customer, priorQuoteCount(steps, index)),
  })),
});
